def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    prev_bids = []
    aggressive = 0
    desperate_opp = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if float(bid) >= 100:
                aggressive += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            desperate_opp += 1

    slots = supply / WATER_REQ
    base = 0.0

    if slots >= 2.0:
        base = 18.0
    else:
        base = 42.0

    if prev_bids:
        high_prev = max(prev_bids)
        low_prev = min(prev_bids)
        if slots >= 2.0:
            if high_prev >= 110:
                base = min(base, 16.0)
            elif high_prev >= 80:
                base = max(base, 22.0)
            else:
                base = max(base, low_prev + 2.0)
                base = min(base, 32.0)
        else:
            if high_prev >= 110:
                base = 78.0
            elif high_prev >= 80:
                base = 66.0
            else:
                base = max(base, high_prev + 3.0)

    if aggressive >= 2 and slots >= 2.0:
        base = min(base, 15.0)

    if desperate_opp >= 2 and slots < 2.0:
        base = max(base, 82.0)

    if hp <= 2 or no_water >= 2:
        base = max(base, 96.0)
    elif hp <= 4 or no_water >= 1:
        base = max(base, 72.0)

    if budget < 40:
        base = min(base, budget)
    elif budget < 90 and (hp > 4 and no_water == 0 and slots >= 2.0):
        base = min(base, 24.0)

    if not alive:
        base = 20.0 if hp > 3 else 60.0

    bid = min(float(budget), float(base))
    if bid < 0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append(opp)

    # If no opponents are alive, conserve.
    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from traces for immediate pressure.
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {}) or {}
        if prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many full allocations might be available.
    # Ensure integer indices if we ever use arrays; here we only use scalar math.
    est_slots = int(supply / float(WATER_REQ)) if WATER_REQ > 0 else 0

    # Base bid: react to yesterday's aggressiveness.
    # If others were bidding near/above daily salary, we must match more.
    pressure_ratio = highest_prev_bid / DAILY_SALARY if DAILY_SALARY > 0 else 0.0

    if pressure_ratio >= 0.85:
        # High competitive environment.
        if hp > 3.0 and no_water_days <= 0:
            target = DAILY_SALARY * 0.30
        elif hp > 3.0:
            target = DAILY_SALARY * 0.45
        else:
            target = DAILY_SALARY * 0.85
    else:
        # Moderate environment: bid enough to secure but not burn budget.
        # Slightly above yesterday max to counter conservative bids.
        target = max(DAILY_SALARY * 0.50, highest_prev_bid + 1.5)

    # Adjust for my health urgency.
    if hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.95)
    elif hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.65)

    # If supply looks low (few slots), bidding more is safer.
    if est_slots <= 1:
        target = max(target, DAILY_SALARY * 0.70)

    # Final cap by budget.
    if budget <= 0.0:
        return 0.0

    bid = float(min(budget, target))

    # Ensure non-negative and at least a minimal competitive bid when possible.
    if bid < 0.0:
        bid = 0.0
    if bid == 0.0 and budget > 0.0:
        bid = float(min(budget, DAILY_SALARY * 0.10))

    return bid

