def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive:
        trace = opp.get('previous_trace', {})
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])

    # Urgency based on hp and no_water_days
    urgent = hp <= 3 or no_water_days >= 2
    if urgent:
        # Need water badly
        needed_bid = min(budget, DAILY_SALARY * 0.9)
        if prev_bids:
            avg_prev = sum(prev_bids) / len(prev_bids)
            # Slightly above average to win
            needed_bid = max(needed_bid, avg_prev + 5)
        return min(budget, needed_bid)
    else:
        # Not urgent, try to conserve
        if prev_bids:
            avg_prev = sum(prev_bids) / int(len(prev_bids))
            # If average is very high, bid just below to avoid overpaying
            if avg_prev > DAILY_SALARY * 0.7:
                return min(budget, avg_prev - 2)
            else:
                return min(budget, max(avg_prev + 3, DAILY_SALARY * 0.3))
        else:
            return min(budget, DAILY_SALARY * 0.5)
